import math

def parse_amount(text):
    """Parse a decimal amount from text.

    Accepts: decimal dot/comma, spaces around input, zero
    Rejects: empty, negative and non-finite values
    """
    text = text.strip()
    if not text:
        raise ValueError("empty input")
    text = text.replace(',', '.')
    try:
        value = float(text)
    except ValueError:
        raise ValueError("non-finite input")
    if value < 0:
        raise ValueError("negative input")
    if math.isnan(value) or math.isinf(value):
        raise ValueError("non-finite input")
    return value
